// CreateQueue create a queue
//
// Parameters:
//
//	name: Switch-safe identifier: no whitespace or control characters, no @ or
//	quotes, and none of \ ^ , | { } $ or the sequence :_:. A name that breaks
//	this is refused with 422 VALIDATION_FAILED (params.field name, params.rule
//	NAME_CHARSET).
//	extNumber: Omit it and the next free number in the queue pool
//	(AICC_QUEUE_RANGE) is allocated — which is what a form should do, because
//	whoever adds a queue is asking for a queue, not for 7004. Supplying one is
//	for a deployment that has to match numbers it does not own.
//	displayName: Optional `string` value serialized in the `displayName` wire
//	field.
//	strategy: How a queue picks among the agents staffing it, in platform
//	vocabulary; the switch spelling is a boundary translation.
//	mohSound: The switch expands a sound before it plays it: it may name a
//	variable (${name} or $${name}), but holds no other ${…} and no control
//	characters. Anything else is refused with 422 VALIDATION_FAILED (params.rule
//	SOUND_EXPANSION).
//	maxWaitSec: Optional `integer` value serialized in the `maxWaitSec` wire
//	field.
//	maxWaitNoAgentSec: Optional `integer` value serialized in the
//	`maxWaitNoAgentSec` wire field.
//	announceSound: The switch expands a sound before it plays it: it may name a
//	variable (${name} or $${name}), but holds no other ${…} and no control
//	characters. Anything else is refused with 422 VALIDATION_FAILED (params.rule
//	SOUND_EXPANSION).
//	announceFrequencySec: Optional `integer` value serialized in the
//	`announceFrequencySec` wire field.
//	tierRules: How a queue widens its agent search over time.
//	discardAbandonedAfterSec: Optional `integer` value serialized in the
//	`discardAbandonedAfterSec` wire field.
//	isAbandonedResumeAllowed: Optional `boolean` value serialized in the
//	`isAbandonedResumeAllowed` wire field.
//	slaThresholdSec: Optional `integer` value serialized in the
//	`slaThresholdSec` wire field.
//	isRecordingEnabled: Optional `boolean` value serialized in the
//	`isRecordingEnabled` wire field.
//	hours: Optional array value serialized in the `hours` wire field.
//	overflow: Where an unserved caller goes. BOT_FLOW and FORWARD need a target.
//	isEnabled: Optional `boolean` value serialized in the `isEnabled` wire
//	field.
func (sdk *CatalogNamespace) CreateQueue(ctx context.Context, params CreateQueueParams, opts ...RequestOption) (*Queue, error) {
	return CreateQueue(ctx, sdk.config, params, opts...)
}

